        return datetime.datetime.fromtimestamp(nanoseconds / 1e9, tz).time()

def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    if tz is None:
        # Assuming LocalTime if no timezone is provided
        from datetime import datetime, timedelta
        return (datetime.min + timedelta(microseconds=nanoseconds / 1000)).time()
    else:
        # Assuming Time with timezone if provided
        from datetime import datetime, timedelta, timezone
        dt = datetime.min + timedelta(microseconds=nanoseconds / 1000)
        return dt.replace(tzinfo=timezone(tz)).time()

