def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    from functools import lru_cache
    from time import monotonic as _time

    def decorator(func):
        cache = lru_cache(maxsize=maxsize, typed=typed)
        timestamps = lru_cache(maxsize=maxsize, typed=typed)

        def wrapper(*args, **kwargs):
            key = args if not kwargs else args + tuple(kwargs.items())
            if key in timestamps.cache_info().hits:
                start_time = timestamps(key)
                if _time() - start_time > ttl:
                    cache.pop(key)
                    timestamps.pop(key)
                else:
                    return cache(key)
            result = func(*args, **kwargs)
            timestamps(key, _time())
            return cache(key, result)

        return wrapper

    return decorator

