                    last_applied_manifest[i], schema, resp[i]
                )
        else:
            for key in obs:
                if key not in last_applied_manifest:
                    last_applied_manifest[key] = resp.get(key, None)

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    for i, (observed, resp_item) in enumerate(zip(observer_schema, response)):
        if i >= len(last_applied_manifest):
            last_applied_manifest.append({} if isinstance(observed, dict) else [])
        if isinstance(observed, dict):
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[i], observed, resp_item
            )
        elif isinstance(observed, list):
            update_last_applied_manifest_list_from_resp(
                last_applied_manifest[i], observed, resp_item
            )
        elif observed not in last_applied_manifest[i]:
            last_applied_manifest[i].append(resp_item)

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    for obs_schema, resp_item in zip(observer_schema, response):
        if isinstance(obs_schema, dict) and isinstance(resp_item, dict):
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest, obs_schema, resp_item
            )
        elif isinstance(obs_schema, list) and isinstance(resp_item, list):
            update_last_applied_manifest_list_from_resp(
                last_applied_manifest, obs_schema, resp_item
            )
        else:
            for key in obs_schema:
                if key not in last_applied_manifest:
                    last_applied_manifest.append(resp_item)
